        imageStageClientWidth: 0,
        imageStageClientHeight: 0,
        imgRectWidth: 0,
        imgRectHeight: 0,
        overlayRectWidth: 0,
        overlayRectHeight: 0,
        previewSrcExists: false,
        imageLoadSuccess: false,
        renderBranch: "placeholder",
        overlayLeft: 0,
        overlayTop: 0,
        overlayWidth: 0,
        overlayHeight: 0
