        visibleFocusRect: currentCapture && currentCapture.visibleFocusRect ? cloneDraft(currentCapture.visibleFocusRect) : null,
        shotRect: currentCapture && currentCapture.shotRect ? cloneDraft(currentCapture.shotRect) : null,
