    if (!m) return c;
    var p = m[1].split(",").map(function (x) {
      return x.trim();
    });
    var r = parseFloat(p[0]) || 0;
    var g = parseFloat(p[1]) || 0;
    var b = parseFloat(p[2]) || 0;
    function hex(n) {
      var h = Math.round(n).toString(16).toUpperCase();
      return h.length === 1 ? "0" + h : h;
    }
