    recordMenuDom.regionBtn = recordMenu.querySelector('[data-v12-action="record-submode-region"]');
    recordMenuDom.elementCheck = recordMenuDom.elementBtn ? recordMenuDom.elementBtn.querySelector(".v12-record-menu-check") : null;
    recordMenuDom.regionCheck = recordMenuDom.regionBtn ? recordMenuDom.regionBtn.querySelector(".v12-record-menu-check") : null;
    recordMenuDom.ready = true;
